# apply_qual_and_run.py — regenerates 3 files and runs baseline-vs-qual comparison
import base64, os, sys, pathlib, subprocess

FILES = {
    'src/features/qualifying.py': '',
    'src/eval/backtest.py': '',
    'tests/test_qualifying.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        content = base64.b64decode(b64)
        p.write_bytes(content)
        print(f"wrote {target} ({len(content)} bytes)")

    print("\n== pytest ==")
    subprocess.run([sys.executable, "-m", "pytest", "tests/", "-q"], check=False)

    print("\n== comparison ==")
    import pandas as pd
    from src.eval.backtest import backtest, summarize
    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")

    print("\n=== BASELINE (no qual feature) ===")
    _, b = backtest(races, entries, burn_in_races=36)
    print(summarize(b).round(4))

    print("\n=== + QUAL SPEED (weight=0.4) ===")
    _, q = backtest(races, entries, burn_in_races=36, sessions=sessions, qual_weight=0.4)
    print(summarize(q).round(4))

if __name__ == "__main__":
    main()
